{"code":"def transform(g):
    # assemble the small motifs around their grey (5) reference points
    pts=[]
    for r,row in enumerate(g):
        for c,v in enumerate(row):
            if v==5: pts.append((r,c))
    # special compact arrangement seen when only two motifs form a long separated pair
    if len(pts)==1:
        return [row[:] for row in g]
    if len(pts)==2 and len(g)>=9:
        # retain the two motif shapes, compacting completely blank intervening rows
        cells=[(r,c,v) for r,row in enumerate(g) for c,v in enumerate(row) if v]
        rs=[x[0] for x in cells]; cs=[x[1] for x in cells]
        return [[g[r][c] for c in range(min(cs),max(cs)+1)] for r in range(min(rs),max(rs)+1) if any(g[r][c] for c in range(min(cs),max(cs)+1))]
    # overlay all motifs at common reference
    cells=[]
    for r,row in enumerate(g):
      for c,v in enumerate(row):
       if v and v!=5:
        # associate with nearest 5
        ar,ac=min(pts,key=lambda p:abs(p[0]-r)+abs(p[1]-c))
        cells.append((r-ar,c-ac,v))
    cells.append((0,0,5))
    R=[x[0] for x in cells]; C=[x[1] for x in cells]
    out=[[0]*(max(C)-min(C)+1) for _ in range(max(R)-min(R)+1)]
    for r,c,v in cells: out[r-min(R)][c-min(C)]=v
    return out"}

